import type { RelayArtifact, RelaySession } from "../types.js";

export function visibleThreadArtifacts(session: RelaySession | undefined): RelayArtifact[] {
  if (!session) return [];
  return (session.artifacts ?? [])
    .filter((artifact) => artifact.kind !== "command_log")
    .slice()
    .sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));
}

function workspaceFileKey(artifact: RelayArtifact): string {
  return artifact.workspaceRelativePath ?? artifact.path ?? artifact.id;
}

/** One entry per generated file, at its newest record — the same rule as the
 *  backend's `workspace_artifacts`. A file re-generated by a later run gets a
 *  fresh artifact per change; lists and counts should name it once. Older
 *  records stay in the session so a transcript chip can still open the
 *  version its run produced. Non-file artifacts pass through; order is kept. */
export function latestThreadArtifacts(artifacts: readonly RelayArtifact[]): RelayArtifact[] {
  const newest = new Map<string, RelayArtifact>();
  for (const artifact of artifacts) {
    if (artifact.kind !== "workspace_file") continue;
    const key = workspaceFileKey(artifact);
    const current = newest.get(key);
    if (!current || (artifact.createdAt || "") >= (current.createdAt || "")) newest.set(key, artifact);
  }
  return artifacts.filter(
    (artifact) => artifact.kind !== "workspace_file" || newest.get(workspaceFileKey(artifact)) === artifact,
  );
}
